	memblock_reserve(0, STARTUP_NORMAL_OFFSET);
	memblock_reserve((unsigned long)sclp_early_sccb, EXT_SCCB_READ_SCP);
	memblock_reserve((unsigned long)_stext, PFN_PHYS(start_pfn)
